# Surah Al-A'raf (chapter 7) — part 4: ayat 31-40 (IDs 985-994)
SURAH = 7

ENTRIES = {
985: (
"اے آدم کی اولاد — ہر سجدہ گاہ پر — اپنی زینت لے لو — اور کھاؤ — اور پیو — اور اسر اف نہ کرو — بے شک وہ — اسر اف کرنے والوں کو — پسند نہیں فرماتا",
"""۱۔ زینت اور رزق — اللہ کی نعمت — اسرافیل ہوشیاری لازم۔
۲۔ ’’يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا وَاشْرَبُوا وَلَا تُسْرِفُوا إِنَّهُ لَا يُحِبُّ الْمُسْرِفِينَ‘‘ — اے آدم کی اولاد — ہر سجدہ گاہ پر — اپنی زینت لے لو — اور کھاؤ — اور پیو — اور اسر اف نہ کرو — بے شک وہ — اسر اف کرنے والوں کو — پسند نہیں فرماتا — یعنی مسجد میں جانے سے پہلے صاف ستھرا اور خوبصورت لباس پہنو؛ رزق — اللہ کی طرف سے ہو تو اسر اف نہ کرو۔
۳۔ عملی سبق: سادگی اختیار کرو؛ نہ تو فقر میں ناچے — نہ زینت کی حرمت سے انکار؛ رزق — اللہ کی عطا ہے۔"""
),
986: (
"کہدو: کون — ہے جس نے — اللہ کی زینت کو — جو اس نے اپنے بندوں کے لیے پیدا کی — حرام کیا — اور پاکیزہ رزق — کہدو: یہ — دنیا کی زندگی میں — ایمان والوں کے لیے ہیں — اور قیامت کے دن — خالص — اس طرح ہم — ان لوگوں کے لیے — آیات کھولتے ہیں جو جانتے ہیں",
"""۱۔ حلال زینت و رزق کی حرمت — غلط بندش۔
۲۔ ’’قُلْ مَنْ حَرَّمَ زِينَۃَ اللَّهِ الَّتِي أَخْرَجَ لِعِبَادِهِ وَالطَّيِّبَاتِ مِنَ الرِّزْقِ قُلْ هِيَ لِلَّذِينَ آمَنُوا فِي الْحَيَاۃِ الدُّنْيَا خَالِصَۃً يَوْمَ الْقِيَامَۃِ كَذَٰلِكَ نُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَعْلَمُونَ‘‘ — کہدو: کون — ہے جس نے — اللہ کی زینت کو — جو اس نے اپنے بندوں کے لیے پیدا کی — حرام کیا — اور پاکیزہ رزق — کہدو: یہ — دنیا کی زندگی میں — ایمان والوں کے لیے ہیں — اور قیامت کے دن — خالص — اس طرح ہم — ان لوگوں کے لیے — آیات کھولتے ہیں جو جانتے ہیں — یعنی حلال چیزوں کو حرام قرار دینا — غلط ہے؛ قیامت میں مومنوں کو خالص طور پر ملے گی۔
۳۔ عملی سبق: حلال و پاکیزہ نعمتوں کو حرام قرار دینا — غلط فتویٰ — قبول نہ کرو۔"""
),
987: (
"کہدو: میرے رب نے — بے حیائی کو — جو ظاہر ہو — اور جو پوشیدہ — گناہ اور ناحق ظلم — اور اللہ کے ساتھ — شرک — جس کی — کوئی دلیل نہیں نازل کی — اور — وہ — کہو جس کے بارے میں تم — کچھ نہیں جانتے — حرام قرار دیا",
"""۱۔ حرام چیزوں کی فہرست — تفصیل سے۔
۲۔ ’’قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَن تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَن تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ‘‘ — کہدو: میرے رب نے — بے حیائی کو — جو ظاہر ہو — اور جو پوشیدہ — گناہ اور ناحق ظلم — اور اللہ کے ساتھ — شرک — جس کی — کوئی دلیل نہیں نازل کی — اور — وہ — کہو جس کے بارے میں تم — کچھ نہیں جانتے — حرام قرار دیا — یعنی چھ — چیزیں حرام ہیں: بے حیائی (ظاہر/باطن)، گناہ، ناحق ظلم، شرک، اللہ پر بے علم بات۔
۳۔ عملی سبق: ان — چھ — بڑی حرمتوں سے بچو؛ یہ سب گناہ ہیں جن کی سزا — جہنم ہے۔"""
),
988: (
"اور ہر امت کے لیے ایک — میعاد ہے — پس جب ان کی میعاد آ جائے — وہ ایک لمحہ بھی — دیر نہیں کر سکتے — اور نہ — آگے بڑھ سکتے ہیں",
"""۱۔ ہر امت کا — مقرر وقت۔
۲۔ ’’وَلِكُلِّ أُمَّۃٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَۃً وَلَا يَسْتَقْدِمُونَ‘‘ — اور ہر امت کے لیے ایک — میعاد ہے — پس جب ان کی میعاد آ جائے — وہ ایک لمحہ بھی — دیر نہیں کر سکتے — اور نہ — آگے بڑھ سکتے ہیں — یعنی ہر قوم کی زندگی کا — اللہ کی طرف سے مقرر وقت ہے — اس میں تبدیلی ممکن نہیں۔
۳۔ عملی سبق: اپنی میعاد سے آگے — کسی کی زندگی نہیں — لہٰذا — اللہ کی یاد میں — زندگی گزارو۔"""
),
989: (
"اے آدم کی اولاد — اگر — تمہارے پاس — تم میں سے — رسول آئیں — جو تمہیں — میری آیات پڑھ کر سنائیں — تو — جو — ڈرے اور — اصلاح کرے — ان پر نہ خوف ہوگا — اور نہ وہ — غمگین ہوں گے",
"""۱۔ رسولوں کی آمد — ہدایت اور نجات کا ذریعہ۔
۲۔ ’’يَا بَنِي آدَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ آيَاتِي فَمَنِ اتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ‘‘ — اے آدم کی اولاد — اگر — تمہارے پاس — تم میں سے — رسول آئیں — جو تمہیں — میری آیات پڑھ کر سنائیں — تو — جو — ڈرے اور — اصلاح کرے — ان پر نہ خوف ہوگا — اور نہ وہ — غمگین ہوں گے — یعنی رسول — تم میں سے بھیجے گئے ہیں — جو ان کی بات مانے — نجات پائے گا۔
۳۔ عملی سبق: رسولوں کی دعوت — سیدھا راستہ ہے؛ اس سے دوری — گمراہی ہے۔"""
),
990: (
"اور جو — ہماری آیات کو جھٹلائیں — اور ان سے تکبر کریں — یہی لوگ — جہنم والے ہیں — وہ اس میں ہمیشہ رہنے والے ہیں",
"""۱۔ تکذیب و تکبر — جہنم کا — راستہ۔
۲۔ ’’وَالَّذِينَ كَذَّبُوا بِآيَاتِنَا وَاسْتَكْبَرُوا عَنْهَا أُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ‘‘ — اور جو — ہماری آیات کو جھٹلائیں — اور ان سے تکبر کریں — یہی لوگ — جہنم والے ہیں — وہ اس میں ہمیشہ رہنے والے ہیں — یعنی آیات کی تکذیب اور تکبر — ہمیشہ کے لئے — جہنم ہے۔
۳۔ عملی سبق: قرآن کو جھٹلانا — سب سے بڑا جرم ہے؛ تکبر — دروازے کھول دیتا ہے جہنم کے۔"""
),
991: (
"پس — اس سے بڑا — ظالم کون ہے — جو اللہ پر جھوٹ گھڑے — یا اس کی آیات کو جھٹلائے — یہی لوگ — ان کا حصہ — کتاب میں — پہنچتا ہے — یہاں تک کہ — جب ہمارے رسول ان کے پاس آئیں — ان کی روحیں نکالنے — تو وہ کہیں — کہاں ہیں — جنہیں تم اللہ کے علاوہ — پکارتے تھے — وہ کہیں گے — وہ ہم سے — گم ہو گئے — اور وہ — اپنی جانوں پر — گواہی دیں گے کہ — وہ کافر تھے",
"""۱۔ اللہ پر جھوٹ گھڑنے والے — سب سے بڑے ظالم۔
۲۔ ’’فَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ بِآيَاتِهِ أُولَٰئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ الْكِتَابِ حَتَّىٰ إِذَا جَاءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوا أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ اللَّهِ قَالُوا ضَلُّوا عَنَّا وَشَهِدُوا عَلَىٰ أَنفُسِهِمْ أَنَّهُمْ كَانُوا كَافِرِينَ‘‘ — پس — اس سے بڑا — ظالم کون ہے — جو اللہ پر جھوٹ گھڑے — یا اس کی آیات کو جھٹلائے — یہی لوگ — ان کا حصہ — کتاب میں — پہنچتا ہے — یہاں تک کہ — جب ہمارے رسول ان کے پاس آئیں — ان کی روحیں نکالنے — تو وہ کہیں — کہاں ہیں — جنہیں تم اللہ کے علاوہ — پکارتے تھے — وہ کہیں گے — وہ ہم سے — گم ہو گئے — اور وہ — اپنی جانوں پر — گواہی دیں گے کہ — وہ کافر تھے — یعنی موت کے وقت پتہ چلتا ہے کہ اللہ کے علاوہ — جو کچھ پوجتے تھے — سب باطل تھے۔
۳۔ عملی سبق: غیر اللہ کو پکارنے کی قیمت — موت کے وقت — سب کی آنکھیں کھول دیتی ہے۔"""
),
992: (
"اللہ کہے گا — تم — ان امتوں میں — جو تم سے پہلے گزر چکے جن و انس میں شامل ہو جاؤ — جہنم میں — جب ہر امت داخل ہو گی — وہ اپنی بہن امت پر لعنت کرے گی — یہاں تک کہ — جب وہ سب اس میں اکٹھی ہوں — تو ان کی بعد آنے والی — پہلی والی سے کہیں — اے ہمارے رب — انہوں نے — ہمیں — گمراہ کیا — پس — انہیں — آگ کا دوہرا عذاب دے — اللہ کہے گا — ہر ایک کے لیے دوہرا ہے — لیکن تم نہیں جانتے",
"""۱۔ جہنم میں باطل حکمران والی امتیں — ایک دوسرے پر لعنت کریں گی۔
۲۔ ’’قَالَ ادْخُلُوا فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ فِي النَّارِ كُلَّمَا دَخَلَتْ أُمَّۃٌ لَّعَنَتْ أُخْتَهَا حَتَّىٰ إِذَا ادَّارَكُوا فِيهَا جَمِيعًا قَالَتْ أُخْرَاهُمْ لِأُولَاهُمْ رَبَّنَا هَٰؤُلَاءِ أَضَلُّونَا فَآتِهِمْ عَذَابًا ضِعْفًا مِّنَ النَّارِ قَالَ لِكُلٍّ ضِعْفٌ وَلَٰكِن لَّا تَعْلَمُونَ‘‘ — اللہ کہے گا — تم — ان امتوں میں — جو تم سے پہلے گزر چکے جن و انس میں شامل ہو جاؤ — جہنم میں — جب ہر امت داخل ہو گی — وہ اپنی بہن امت پر لعنت کرے گی — یہاں تک کہ — جب وہ سب اس میں اکٹھی ہوں — تو ان کی بعد آنے والی — پہلی والی سے کہیں — اے ہمارے رب — انہوں نے — ہمیں — گمراہ کیا — پس — انہیں — آگ کا دوہرا عذاب دے — اللہ کہے گا — ہر ایک کے لیے دوہرا ہے — لیکن تم نہیں جانتے — یعنی گمراہ کرنے والوں اور گمراہ ہونے والوں — دونوں کو دوہرا عذاب ہوگا۔
۳۔ عملی سبق: اپنی گمراہی کی ذمہ داری خود لو؛ باطل دنیا کی پیروی — دوہرے عذاب کا سبب ہے۔"""
),
993: (
"اور ان کی پہلی امت — بعد والی امت سے کہے گی — تو — تمہیں — ہم پر — کوئی فضیلت نہیں — پس — اپنے کیے کا عذاب چکھو",
"""۱۔ گمرہِیاں — ایک دوسرے پر بالادستی کا وہم۔
۲۔ ’’وَقَالَتْ أُولَاهُمْ لِأُخْرَاهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ‘‘ — اور ان کی پہلی امت — بعد والی امت سے کہے گی — تو — تمہیں — ہم پر — کوئی فضیلت نہیں — پس — اپنے کیے کا عذاب چکھو — یعنی گمراہ کرنے والا اور گمراہ ہونے والا — دونوں برابر قصوروار ہیں۔
۳۔ عملی سبق: اپنی گمراہی کو دوسروں پر نہ ڈالو؛ اپنی جواب دہی خود ہو گی۔"""
),
994: (
"بے شک جو — ہماری آیات کو جھٹلائیں — اور — ان سے تکبر کریں — ان کے لیے — آسمان کے دروازے — نہیں کھولے جائیں گے — اور وہ — جنت میں داخل نہیں ہوں گے — یہاں تک کہ — اونٹ سوئی کے سوراخ سے گزر جائے — اور اسی طرح ہم — مجرموں کو — جزا دیتے ہیں",
"""۱۔ تکذیب و تکبر — جنت کے دروازے بند۔
۲۔ ’’إِنَّ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَاسْتَكْبَرُوا عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَابُ السَّمَاءِ وَلَا يَدْخُلُونَ الْجَنَّۃَ حَتَّىٰ يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ وَكَذَٰلِكَ نَجْزِي الْمُجْرِمِينَ‘‘ — بے شک جو — ہماری آیات کو جھٹلائیں — اور — ان سے تکبر کریں — ان کے لیے — آسمان کے دروازے — نہیں کھولے جائیں گے — اور وہ — جنت میں داخل نہیں ہوں گے — یہاں تک کہ — اونٹ سوئی کے سوراخ سے گزر جائے — اور اسی طرح ہم — مجرموں کو — جزا دیتے ہیں — یعنی جنت میں داخلہ — تکذیب و تکبر والوں کے لیے — ناممکن ہے (اونٹ — سوئی کے سوراخ کا محاورہ)۔
۳۔ عملی سبق: قرآن کی تصدیق اور عاجزی — جنت کے دروازے کھولتے ہیں۔"""
),
}
